window.docContents[133].resolve({"/#Core-C______":{"contents":"Core C++ is a subset of C++17 with an LL(1) grammar, a deterministic semantics and no undefined behaviour. This blueprint holds the lexer, the grammar, and the typing and evaluation rules in natural semantics, in the sequent style of Kahn (1987), and points each rule to the Lean code that implements it in core-cpp/CoreCpp/. The source, the interpreter and this blueprint live in the repository github.com/ChristianoBraga/corecpp. One chapter per group of constructions, one node per construction or nonterminal. The design lists no construction the blueprint leaves out.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"","header":"Core C++","id":"/#Core-C______"}});